INSERT INTO "business_knowledge" ("id", "business_term", "description", "synonyms", "is_recall", "embedding_status", "error_msg", "create_by", "create_name", "create_time", "last_modify_by", "last_modify_name", "last_modify_time", "deleted", "skill_id", "superseded_by_id", "tenant_id") VALUES (2082712687667363841, '额外费用', '额外费用是应收结算模块下，除基础租赁、仓储常规账单外，单独登记、分应收 / 应付类型、关联客户与账期、可统一查询新增导出的杂项收支单据，用于核算各类附加费用。', '杂项收支单据,核算各类附加费用', true, 'COMPLETED', NULL, 'sn68', 'sn68', '2026-07-30 06:19:34.334572', 'sn68', 'sn68', '2026-07-30 06:19:34.545690', false, 2082710652612034561, NULL, 'default');
